heldXSRow = gRow + r;
heldXSRows = nr;
}
PipeBarrier<PIPE_V>();
MulByRow(accF, accF, tileWS, nr, nt, pitch);
PipeBarrier<PIPE_V>();
MulByTokenScale(accF, xsb, nr, nt, pitch);
PipeBarrier<PIPE_V>();
