}
template<int V,uint32_t Mode> void Launch(GM_ADDR x,GM_ADDR w,GM_ADDR xs,GM_ADDR ws,GM_ADDR gl,GM_ADDR y,Plan p,aclrtStream stream){
if constexpr(V>=14)p.wstride=1152;
